// were pushed verbatim and untagged.
func TestPushQueuedCheckpointRefs_OPFAppliedBeforePush(t *testing.T) {
	workDir, bareDir, refs := setupRepoWithCheckpointRefs(t)
	t.Chdir(workDir)
	paths.ClearWorktreeRootCache()

	fake := &fakeOPFForRewrite{}
	configureFakeOPF(t, fake)

	repo, err := git.PlainOpen(workDir)
	require.NoError(t, err)
	queue := enqueueRefs(t, repo, refs)

	pushed, pushDisabled, err := PushQueuedCheckpointRefs(context.Background(), repo, bareDir)
	require.NoError(t, err)
	assert.False(t, pushDisabled)
	assert.Equal(t, len(refs), pushed)
	assert.Equal(t, 1, fake.batchCallCount(), "exactly one OPF invocation for the whole flush")

	for _, ref := range refs {
		hash := remoteRefHash(t, bareDir, ref)
		require.NotEmpty(t, hash, "ref should be on the remote")
		assert.True(t, trailers.HasOPFApplied(remoteCommitMessage(t, bareDir, hash)),
			"content reaching the remote must be OPF-applied, not 8-layer-only")
	}

	remaining, err := queue.Drain()
	require.NoError(t, err)
	assert.Empty(t, remaining, "pushed refs are removed from the queue")
}

// TestPushQueuedCheckpointRefs_OPFFailureWithholdsPush is the fail-closed half:
// when OPF is enabled but the rewrite cannot run, nothing may reach the remote.
// Unlike the pre-push path — which withholds silently so the user's own git push
// is never blocked — this push was explicitly requested, so the failure is
// surfaced as an error with the refs left queued.
func TestPushQueuedCheckpointRefs_OPFFailureWithholdsPush(t *testing.T) {
	workDir, bareDir, refs := setupRepoWithCheckpointRefs(t)
	t.Chdir(workDir)
	paths.ClearWorktreeRootCache()

	configureFakeOPF(t, &fakeRuntimeAlwaysFails{})

	repo, err := git.PlainOpen(workDir)
	require.NoError(t, err)
	queue := enqueueRefs(t, repo, refs)

	pushed, pushDisabled, err := PushQueuedCheckpointRefs(context.Background(), repo, bareDir)
	require.Error(t, err)
	assert.False(t, pushDisabled)
	assert.Equal(t, 0, pushed)

	remaining, err := queue.Drain()
	require.NoError(t, err)
	assert.ElementsMatch(t, refs, remaining, "withheld push leaves refs queued")

	lsCmd := exec.CommandContext(context.Background(), "git", "ls-remote", bareDir)
	lsCmd.Env = testutil.GitIsolatedEnv()
	out, lsErr := lsCmd.CombinedOutput()
	require.NoError(t, lsErr, "ls-remote failed: %s", out)
	for _, ref := range refs {
		assert.NotContains(t, string(out), ref.String(), "withheld push must not reach the remote")
	}
}

// remoteCommitMessage returns the message of a commit on the bare remote.
func remoteCommitMessage(t *testing.T, bareDir, hash string) string {
	t.Helper()
	c := exec.CommandContext(context.Background(), "git", "-C", bareDir, "log", "-1", "--format=%B", hash)
	c.Env = testutil.GitIsolatedEnv()
	out, err := c.CombinedOutput()
	require.NoError(t, err, "git log failed: %s", out)
	return string(out)
}
