func run(dir string, args ...string) (string, error) {
	c := exec.Command("git", args...)
	c.Dir = dir
	var sb strings.Builder
	c.Stdout = &sb
	c.Stderr = &sb
	err := c.Run()
	return strings.TrimSpace(sb.String()), err
}

func mustRun(dir string, args ...string) string {
	out, err := run(dir, args...)
	if err != nil {
		panic(fmt.Sprintf("git %v: %v: %s", args, err, out))
	}
	return out
}

// prepareTx starts `git update-ref --stdin`, drives it to the prepared state
// (where git holds the ref lock), and returns the live process.
func prepareTx(dir, ref, newHash, oldHash string) (*exec.Cmd, io.WriteCloser, *bufio.Scanner) {
	cmd := exec.Command("git", "update-ref", "--stdin")
	cmd.Dir = dir
	stdin, _ := cmd.StdinPipe()
	stdoutPipe, _ := cmd.StdoutPipe()
	cmd.Stderr = os.Stderr
	if err := cmd.Start(); err != nil {
		panic(err)
	}
	stdout := bufio.NewScanner(stdoutPipe)
	exch := func(req, want string) {
		fmt.Fprintln(stdin, req)
		if want == "" {
			return
		}
		if !stdout.Scan() {
			panic("no response to " + req)
		}
		if got := stdout.Text(); got != want {
			panic(fmt.Sprintf("response to %q was %q, want %q", req, got, want))
		}
	}
	exch("start", "start: ok")
	exch("option no-deref", "")
	exch(fmt.Sprintf("update %s %s %s", ref, newHash, oldHash), "")
	exch("prepare", "prepare: ok")
	return cmd, stdin, stdout
}

func main() {
	ver, _ := run(".", "--version")
	fmt.Println(ver)

	const ref = "refs/entire/checkpoints/aa/testcheckpoint"

	scenario := func(name string, finish func(cmd *exec.Cmd, stdin io.WriteCloser)) {
		dir, _ := os.MkdirTemp("", "lockrepro")
		defer os.RemoveAll(dir)
		mustRun(dir, "init", "-q")
		mustRun(dir, "config", "user.email", "t@t.t")
		mustRun(dir, "config", "user.name", "t")
		os.WriteFile(filepath.Join(dir, "f.txt"), []byte("x"), 0o644)
		mustRun(dir, "add", "f.txt")
		mustRun(dir, "commit", "-q", "--no-gpg-sign", "-m", "init")
		head := mustRun(dir, "rev-parse", "HEAD")
		mustRun(dir, "update-ref", ref, head)
		os.WriteFile(filepath.Join(dir, "f.txt"), []byte("y"), 0o644)
		mustRun(dir, "add", "f.txt")
		mustRun(dir, "commit", "-q", "--no-gpg-sign", "-m", "second")
		second := mustRun(dir, "rev-parse", "HEAD")

		fmt.Printf("\n=== %s ===\n", name)
		cmd, stdin, _ := prepareTx(dir, ref, second, head)

		lockPath := filepath.Join(dir, ".git", ref+".lock")
		_, statErr := os.Stat(lockPath)
		fmt.Printf("  ref lock held while prepared: %v\n", statErr == nil)

		finish(cmd, stdin)

		_, statErr = os.Stat(lockPath)
		fmt.Printf("  ref lock left behind after:   %v\n", statErr == nil)

		// Can any later writer touch the ref? This is what a developer's own
		// `git update-ref` / `git push` would hit.
		out, err := run(dir, "update-ref", ref, head)
		if err != nil {
			fmt.Printf("  later plain `git update-ref` FAILS: %s\n", out)
		} else {
			fmt.Printf("  later plain `git update-ref` succeeds\n")
		}
	}

	// What exec.CommandContext's default cancel does when ctx is cancelled.
	scenario("SIGKILL while prepared (exec.CommandContext default cancel)", func(cmd *exec.Cmd, stdin io.WriteCloser) {
		if err := cmd.Process.Kill(); err != nil {
			panic(err)
		}
		_ = cmd.Wait()
	})

	// The recommended alternative.
	scenario("close stdin while prepared", func(cmd *exec.Cmd, stdin io.WriteCloser) {
		_ = stdin.Close()
		err := cmd.Wait()
		fmt.Printf("  git exit: %v\n", err)
	})
}
EOF
